def f(n: int, m: int, k: int, coordinates: List[Tuple[int, int]]) -> int:
    dx = [1, 0, -1, 0]
    dy = [0, 1, 0, -1]
    start = coordinates[0]
    end = coordinates[-1]
    vis = set()

    def bfs():
        bst = set((x, y) for x in range(n) for y in range(m))
        bst.discard(start)
        vis.add(start)
        q = [start]
        while q:
            x, y = q.pop(0)
            for i in range(4):
                nx, ny = x + dx[i], y + dy[i]
                if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in vis and (nx, ny) in bst :
                    if (nx, ny) == end:
                        return True
                    vis.add((nx, ny))
                    q.append((nx, ny))
        return False

    return bfs()
